from fractions import Fraction
from math import inf

def integer_valuation(n, p):
    if n == 0: return inf
    c = 0; n = abs(n)
    while n % p == 0: n //= p; c += 1
    return c

def v(x, p):
    if x == 0: return inf
    return integer_valuation(x.numerator, p) - integer_valuation(x.denominator, p)

def trop_mul(a, b):
    return inf if (a == inf or b == inf) else a + b

for p in (3, 5, 7):
    for x, y in [(Fraction(p**2), Fraction(p)), (Fraction(6), Fraction(10)),
                 (Fraction(1, p), Fraction(p**3))]:
        assert v(x*y, p) == trop_mul(v(x, p), v(y, p))
        print(f'p={p}: v({x}*{y}) = {v(x*y, p)} (exact)')
print('Multiplicativity is exact for every sample.')

